# Registered migrations: name -> {"type": ..., "up": callable, "down": callable or None}.
MIGRATIONS = {}


def register_migration(name, up, down=None, migration_type="db"):
    MIGRATIONS[name] = {"type": migration_type, "up": up, "down": down}


def run_migrations(migrations=None):
    """Apply pending migrations in name order, skipping those already applied.

    A migration is recorded only after it completes; when one fails it is rolled
    back (its ``down`` callable runs) and its record is removed. Returns the names
    of the migrations that were applied.
    """
    migrations = MIGRATIONS if migrations is None else migrations
    applied = []
    for name in sorted(migrations):
        spec = migrations[name]
        migration_type = spec.get("type", "db")
        if Migration.is_applied(name, migration_type):
            continue
        debug("Running migration: %s" % name, "migrations")
        try:
            spec["up"]()
        except Exception as exc:
            rollback_migration(name, spec)
            raise MigrationError("Migration '%s' failed: %s" % (name, exc))
        Migration.create(name, migration_type)
        applied.append(name)
    return applied


def rollback_migration(name, spec=None):
    """Undo ``name`` and remove its record from the migration history."""
    spec = spec or MIGRATIONS[name]
    migration_type = spec.get("type", "db")
    if spec.get("down"):
        try:
            spec["down"]()
        finally:
            Migration.delete(name, migration_type)
    else:
        Migration.delete(name, migration_type)


